  'modules.always': 'हमेशा चालू',
  'modules.whenOff': 'बंद होने पर:',
  'modules.ask': 'किसी को चालू या बंद करने के लिए टिकट भेजें, NetCyberAI आपके साथ मिलकर कर देगा।',
  'modules.later': 'अभी बने नहीं हैं ({count})',
