  'tt.about.office': 'कक्षा चुनें, फिर कोई पीरियड भरने, बदलने या खाली करने के लिए उस पर टैप करें। एक शिक्षक को एक ही समय पर दो कक्षाओं में नहीं रखा जा सकता, और जहाँ सेटअप किसी कक्षा का विषय कुछ शिक्षकों को देता है, उसके पीरियड वही लेते हैं। हफ़्ते के नीचे: हर शिक्षक के हफ़्ते के पीरियड, और CSV फ़ाइल से इम्पोर्ट।',
