  'cost.month.about': 'भारत के कैलेंडर के एक महीने में हर लाइव स्कूल के WhatsApp संदेशों का ख़र्च, सेंड-गेट के अपने रिकॉर्ड से, स्कूल की सीमा के साथ।',
  'cost.month.counts': '{month} के लिए, भारत के कैलेंडर से: ख़र्च वह है जो पहुँचे हुए, बिल योग्य संदेशों पर GST सहित लगा, उस दाम पर जो भेजते समय दर्ज हुआ; रास्ते में वे हैं जो भेजे गए पर जिनके पहुँचने की पुष्टि अभी नहीं हुई, और वे ख़र्च नहीं हैं; सीमा में गिना गया वह है जो सेंड-गेट कोई संदेश जाने देने से पहले जोड़ता है, यानी ख़र्च और दाम लगे वे संदेश जो भेजे गए पर जिनके पहुँचने की पुष्टि अभी नहीं हुई; सीमा के कारण रोके गए वे हैं जिन्हें इसी जाँच ने रोका, या जिन्हें बिना सीमा वाला स्कूल भेज नहीं सका; रोके गए, दर की पुष्टि नहीं वे असली खाते के संदेश हैं जिनकी श्रेणी की कोई दर लागू नहीं थी; कोशिशें हर दर्ज संदेश हैं, उसका जो भी हुआ हो।',
