  'monitoring.nightly.billing.how': 'बिलिंग की जाँच का पता ऐसे चलता है: जब कोई स्कूल अपनी भुगतान की तारीख़ से आगे नहीं है तब वह कुछ नहीं बदलती, इसलिए उस रात का उसका अपना काम पढ़ा जाता है।',
  'monitoring.nightly.queued.do': 'उस रात का काम क़तार में लगा पर किसी ने उसे शुरू नहीं किया, इसलिए पढ़ने को कोई गड़बड़ी नहीं है। काम चलाने वाला पीछे है या रुक गया है: ऊपर सेहत की जाँच देखें, और देखें कि शेड्यूलर उसे अब भी हर मिनट बुला रहा है।',
  'monitoring.nightly.running.do': 'उस रात का काम अभी चल रहा है (कोशिश {attempts})। कुछ मिनट बाद यह पेज दोबारा खोलें। अगर वह आगे न बढ़ा हो तो चलाने वाला बीच में रुक गया: तब वह काम ऊपर “चलते-चलते अटके” में गिना जाता है, और काम चलाने वाला अगले चक्कर में उसे फिर उठा लेता है।',
  'monitoring.nightly.retrying.do': 'उस रात का काम विफल हुआ और अगली कोशिश का इंतज़ार कर रहा है (अब तक की कोशिशें: {attempts})। उसकी गड़बड़ी ऊपर विफल कामों में है।',
  'monitoring.nightly.failed.do': 'उस रात के काम ने हार मान ली। उसे ऊपर विफल कामों में ढूँढें, गड़बड़ी पढ़ें और “दोबारा चलाएँ” चुनें।',
  'monitoring.nightly.not_queued.do': 'उस रात के लिए कोई काम क़तार में नहीं लगा, यानी शेड्यूलर नहीं चला। उसकी रात वाली प्रविष्टियाँ जाँचें। जिस डेटाबेस में शेड्यूलर नहीं है, जैसे परीक्षण की प्रति, वहाँ ऐसा होना ठीक है।',
  'monitoring.nightly.missing': 'बकाया वाले स्कूल जिनकी फ़ीस की जाँच न उस रात हुई, न उसके बाद',
  'monitoring.nightly.missing.none': 'बकाया वाले हर लाइव स्कूल की उस रात फ़ीस की जाँच हुई: {expected} में से {done}।',
  'monitoring.nightly.missing.noneLeft': 'बकाया वाला कोई लाइव स्कूल अब फ़ीस की जाँच का इंतज़ार नहीं कर रहा। {expected} में से {done} की जाँच उसी रात हुई; बाक़ी नीचे दिए हैं।',
  'monitoring.nightly.missing.noDues': 'उस दिन से पहले किसी लाइव स्कूल का कोई बकाया दर्ज नहीं था, इसलिए फ़ीस की कोई जाँच होनी नहीं थी।',
  'monitoring.nightly.missing.do': 'इन स्कूलों की फ़ीस की जाँच न उस रात हुई, न उसके बाद, इसलिए जो फ़ीस देर हुई वह चिह्नित नहीं है और विलंब शुल्क नहीं निकाले गए हैं। अगर उस रात का काम ऊपर विफल कामों में बंद पड़ा है तो उस पर “दोबारा चलाएँ” चुनें: देर से शुरू हुई फ़ीस की जाँच आज के लिए चलती है, और हर स्कूल को ताज़ा कर देती है। नहीं तो अगली रात की जाँच यह कर देती है।',
  'monitoring.nightly.caughtUp': 'उस रात छूटे, बाद में ताज़ा हो गए',
  'monitoring.nightly.caughtUp.line': '{school}: {date} की फ़ीस की जाँच से',
  'monitoring.nightly.caughtUp.note': 'इनके लिए कुछ करना नहीं है। बाद की फ़ीस की जाँच हर देर हुई फ़ीस चिह्नित करती है और हर वह विलंब शुल्क निकालती है जो छूटी हुई रात निकालती। उस रात की अपनी कोई पंक्ति नहीं रहती: देर से शुरू हुई जाँच उसी दिन के लिए चलती है जो तब होता है, इसलिए दोबारा चलाने से वह पंक्ति नहीं बनती।',
  'monitoring.nightly.problems': 'स्कूल जिनकी सबसे नई फ़ीस की जाँच में आँकड़े मेल नहीं खाए',
  'monitoring.nightly.problem.one': '{school}: {count} जगह, {date} की रात',
  'monitoring.nightly.problem.other': '{school}: {count} जगहों पर, {date} की रात',
  'monitoring.nightly.problems.do': 'स्कूल का फ़ीस पेज उसे टिकट उठाने को कहता है। “इनकी तरह देखें” से स्कूल खोलें, फ़ीस पेज पढ़ें, और स्कूल के साथ मिलकर प्रविष्टियाँ ठीक करें।',
  'monitoring.templates.title': 'संदेश टेम्पलेट',
  'monitoring.templates.how': 'दर्ज हर संस्करण, हमारी अपनी मंज़ूरी और Meta की मंज़ूरी के हिसाब से। किसी संस्करण के शब्द कभी नहीं बदलते, इसलिए नया संस्करण उसकी जगह ले ले तब भी पुराना दर्ज रहता है।',
