  'monitoring.templates.none': 'अभी कोई टेम्पलेट दर्ज नहीं है। “संदेश टेम्पलेट” खोलें और कोड में लिखे संस्करण ले आएँ।',
  'monitoring.templates.waitingForUs.do': '“संदेश टेम्पलेट” खोलें, शब्द पढ़ें और हर संस्करण को मंज़ूर या अस्वीकार करें। तब तक वह संस्करण नहीं भेजा जाता।',
  'monitoring.templates.refusedByMeta.do': 'जिस संस्करण को Meta ने अस्वीकार किया या रोका है, वह असली खाते से नहीं भेजा जाता, और उस टेम्पलेट के किसी नए संस्करण को अभी दोनों मंज़ूरियाँ नहीं मिली हैं। नए शब्द कोड में नए संस्करण के रूप में लिखें, फिर उसे Meta को भेजें। यह तब हटता है जब किसी नए संस्करण को हमारी और Meta की मंज़ूरी मिल जाए, या जब इसी संस्करण के लिए Meta का बाद का जवाब मंज़ूरी के रूप में दर्ज हो। अगर पुराने शब्द ही रखने हैं तो अस्वीकार हुए संस्करण को “संदेश टेम्पलेट” में अस्वीकार कर दें।',
  'monitoring.templates.settled.one': 'ऊपर इंतज़ार, अस्वीकार या रोके गए में गिना {count} संस्करण अब कुछ नहीं माँगता: उसी टेम्पलेट के नए संस्करण ने उसकी जगह ले ली है, या हमने उसे ख़ुद अस्वीकार किया।',
  'monitoring.templates.settled.other': 'ऊपर इंतज़ार, अस्वीकार या रोके गए में गिने {count} संस्करण अब कुछ नहीं माँगते: उसी टेम्पलेट के नए संस्करणों ने उनकी जगह ले ली है, या हमने उन्हें ख़ुद अस्वीकार किया।',
  'monitoring.templates.hindiNotReviewed.note': 'हिन्दी संस्करण तभी भेजा जाता है जब कोई हिन्दी पढ़ने वाला उसके शब्दों की समीक्षा कर चुका हो; तब तक अभिभावकों को अंग्रेज़ी वाला मिलता है। हर समीक्षा “संदेश टेम्पलेट” में दर्ज करें।',
  'monitoring.templates.withMeta.note': 'जब तक संस्करण Meta के पास है, कुछ करना नहीं है; बस Meta का जवाब आने पर उसे दर्ज करें।',
  'monitoring.templates.open': 'संदेश टेम्पलेट खोलें',
  'monitoring.invites.title': 'न्योते जिन्हें आपकी ज़रूरत है',
  'monitoring.invites.how': 'इस पेज की अकेली सूची जो किसी व्यक्ति के बारे में है: स्कूल का बुलाया हुआ कोई कर्मचारी, कभी कोई अभिभावक या बच्चा नहीं। यहाँ उनके ईमेल का केवल पहला अक्षर और डोमेन दिखता है।',
  'monitoring.invites.none': 'कोई नहीं। किसी स्कूल का ऐसा न्योता, जो उस ईमेल को गया हो जिसका NetCyberAI खाता पहले से है, यहाँ रुकता।',
  'monitoring.invites.line': '{school} ने {email} को {role} के रूप में बुलाया। उस ईमेल का खाता पहले से है, इसलिए कुछ जोड़ा नहीं गया। पूरा पता स्कूल से पूछें, और जोड़ने से पहले खाते के मालिक से पुष्टि करें।',
