  // Reports (C207).
  'moduleOff.reports': '“रिपोर्ट” दफ़्तर, अकाउंटेंट और कोऑर्डिनेटर के मेनू से हट जाएगी। कोई रिपोर्ट खोली या डाउनलोड नहीं की जा सकेगी। हर रिपोर्ट जिन रिकॉर्ड को पढ़ती है वे अपने मॉड्यूल में बने रहेंगे।',
  'rpt.page.title': 'रिपोर्ट',
  'rpt.page.purpose': 'आपके चुने दिनों की तालिकाएँ, कुल के साथ और CSV फ़ाइल।',
  'rpt.page.info': 'आपके चुने दिनों के लिए स्कूल की तालिकाएँ, हर एक के साथ कुल की पंक्ति और ठीक उन्हीं पंक्तियों की CSV फ़ाइल।',
  'tour.reports.1.title': 'आपकी रिपोर्ट',
  'tour.reports.1.text': 'हर रिपोर्ट आपके स्कूल की एक तालिका है। आपको वही रिपोर्ट दिखती हैं जो आपकी भूमिका पढ़ सकती है।',
  'tour.reports.2.title': 'दिन चुनें',
  'tour.reports.2.text': '“आज”, “7 दिन”, “30 दिन” या अपनी दो तारीख़ें। तालिका और उसका कुल उन दिनों के लिए फिर से निकाला जाता है।',
  'tour.reports.3.title': 'कुल और फ़ाइल',
  'tour.reports.3.text': 'आख़िरी पंक्ति ऊपर की पंक्तियों का जोड़ है। “CSV डाउनलोड करें” ठीक यही पंक्तियाँ सेव करता है, और हर डाउनलोड दर्ज होता है।',
  'rpt.list.title': 'आपकी रिपोर्ट',
  'rpt.list.how': 'कोई रिपोर्ट चुनें, वह नीचे खुलेगी। हर रिपोर्ट खोलते समय आपके स्कूल के अपने रिकॉर्ड से गिनी जाती है।',
