  'rpt.none.do': 'रिपोर्ट प्रधानाचार्य, स्कूल एडमिन, अकाउंटेंट और एकेडमिक कोऑर्डिनेटर के लिए हैं। आज का आपका अपना काम मेरा दिन पर है।',
