  'tour.school-auditor.1.text': 'लागू होने वाली जाँचों में से कितनी ठीक हैं। हर जाँच ठीक है, ध्यान चाहती है, या अभी शुरू नहीं हुई। कभी प्रतिशत या ग्रेड नहीं।',
