  // Early Warning v1 (docs/26 slice 8j, C209): flags for staff, by rules. A flag is a reason to look, not a verdict.
  'moduleOff.early-warning': '“समय रहते चेतावनी” मेनू से हट जाएगा। कोई जाँच नहीं चला सकेगा, न लिख सकेगा कि क्या किया गया; शिक्षकों को अपनी कक्षाओं के संकेत नहीं दिखेंगे, और इसके कार्ड “मेरा दिन” से हटेंगे। दर्ज संकेत बने रहेंगे।',
  'tour.early-warning.1.title': 'संकेत देखने का एक कारण है',
  'tour.early-warning.1.text': 'संकेत बताता है कि हाज़िरी, होमवर्क, मदद के किसी फ़ॉलो-अप या परीक्षा के अंकों पर नज़र डालनी चाहिए। यह बच्चे के बारे में कोई फ़ैसला नहीं है।',
  'tour.early-warning.2.title': 'हर संकेत अपना कारण बताता है',
  'tour.early-warning.2.text': '“यह क्यों दिख रहा है?” में वे दिन और होमवर्क दिखते हैं जिन पर यह टिका है, नियम और उसका संस्करण, और पिछली जाँच का समय।',
  'tour.early-warning.3.title': 'लिखें कि क्या किया गया',
  'tour.early-warning.3.text': 'जो क़दम उठाया और उससे क्या हुआ, वह जोड़ें। कारण न रहने पर संकेत अपने आप बंद हो जाता है। अभिभावक को कुछ नहीं जाता।',
  'today.flags-no-action.todo.one': '{count} संकेत पर अभी कोई क़दम नहीं लिखा गया है',
  'today.flags-no-action.todo.other': '{count} संकेतों पर अभी कोई क़दम नहीं लिखा गया है',
  'today.flags-no-action.action': 'समय रहते चेतावनी खोलें',
  'today.flags-no-action.why': 'किसी बच्चे के लिए संकेत खुला है और किसी ने नहीं लिखा कि उस पर क्या किया गया। संकेत देखने का एक कारण है, कोई फ़ैसला नहीं।',
  'today.flags-own-classes.todo.one': 'आपकी कक्षाओं के {count} बच्चे के लिए संकेत खुला है',
  'today.flags-own-classes.todo.other': 'आपकी कक्षाओं के {count} बच्चों के लिए संकेत खुले हैं',
  'today.flags-own-classes.action': 'संकेत देखें',
  'today.flags-own-classes.why': 'स्कूल की जाँच को आपके पढ़ाए किसी बच्चे की हाज़िरी, होमवर्क, मदद के फ़ॉलो-अप या परीक्षा के अंकों में देखने का कारण मिला। कारण देखने और जो आपने किया वह लिखने के लिए इसे खोलें।',
  'set.early-warning.attendance_below.label': 'हर 100 दिनों में इतने से कम दिन स्कूल में',
  'set.early-warning.attendance_below.help': 'हाज़िरी तब देखने का कारण बनती है जब बच्चा हाज़िरी लगे हर 100 दिनों में इतने से कम दिन स्कूल में रहा हो, उपस्थित या देर से, 1 से 100 तक। दर्ज छुट्टी के दिन नहीं गिने जाते।',
  'set.early-warning.window_days.label': 'इतने दिन पीछे तक देखना',
  'set.early-warning.window_days.help': 'हाज़िरी कितने दिन पीछे तक गिनी जाए, आज को मिलाकर, 7 से 90 तक, और नीचे दिए ज़रूरी हाज़िरी के दिनों से कभी कम नहीं।',
  'set.early-warning.min_marked_days.label': 'तभी, जब कम से कम इतने दिन हाज़िरी लगी हो',
  'set.early-warning.min_marked_days.help': 'जब तक उन दिनों में से इतने दिनों पर छुट्टी के अलावा कोई निशान न हो, हाज़िरी इस्तेमाल नहीं होती, 1 से 60 तक, और ऊपर दिए पीछे देखने के दिनों से कभी ज़्यादा नहीं। कम दिनों में एक-दो अनुपस्थितियाँ जितनी हैं उससे बड़ी लगतीं।',
