  'ew.page.about': 'वे बच्चे जिनकी हाज़िरी, होमवर्क, मदद का कोई फ़ॉलो-अप या परीक्षा के अंक देखने का कारण देते हैं, कारण के साथ, और यह कि क्या किया गया।',
