  'monitoring.schoolChecks.how': 'भारत में आधी रात के ठीक बाद, जिस स्कूल में Early Warning चालू है उसकी रात की जाँच होती है; हर सोमवार सुबह-सुबह, जिस स्कूल में School Health Auditor चालू है उसकी हफ़्ते की जाँच होती है। हर स्कूल का एक काम। यहाँ {night} की रात के और {week} से शुरू हफ़्ते के काम पढ़े जाते हैं। सिर्फ़ असली स्कूल; किसी स्कूल का नाम नहीं।',
