  'monitoring.schoolChecks.queued.do': 'इनमें से कुछ काम क़तार में लगे पर किसी ने उन्हें शुरू नहीं किया, इसलिए पढ़ने को कोई गड़बड़ी नहीं है। काम चलाने वाला पीछे है या रुक गया है: ऊपर सेहत की जाँच देखें।',
  'monitoring.schoolChecks.running.do': 'इनमें से कुछ काम अभी चल रहे हैं (कोशिश {attempts})। कुछ मिनट बाद यह पेज दोबारा खोलें। अगर वे आगे न बढ़े हों तो चलाने वाला बीच में रुक गया: तब वे ऊपर “चलते-चलते अटके” में गिने जाते हैं, और काम चलाने वाला उन्हें फिर उठा लेता है।',
  'monitoring.schoolChecks.retrying.do': 'इनमें से कुछ काम विफल हुए और अगली कोशिश का इंतज़ार कर रहे हैं (अब तक की कोशिशें: {attempts})। उनकी गड़बड़ियाँ ऊपर विफल कामों में हैं।',
  'monitoring.schoolChecks.failed.do': 'इनमें से कुछ कामों ने हार मान ली। उन्हें ऊपर विफल कामों में ढूँढें, गड़बड़ी पढ़ें और “दोबारा चलाएँ” चुनें। देर से चलने वाली जाँच स्कूल को उसी समय की हालत में जाँचती है।',
  'monitoring.schoolChecks.not_queued.do': 'कोई काम क़तार में नहीं लगा, जबकि किसी असली स्कूल में यह मॉड्यूल चालू है। या तो शेड्यूलर नहीं चला, या काम चलाने वाले ने अभी नहीं बताया कि वह ये जाँचें चलाता है (वह deploy के बाद अपने पहले चक्कर में बताता है)। शेड्यूलर की प्रविष्टियाँ और ऊपर सेहत की जाँच देखें। जिस डेटाबेस में शेड्यूलर नहीं है, जैसे परीक्षण की प्रति, वहाँ ऐसा होना ठीक है।',
