  'rc.card.ownOnly': 'ये {name} की तुलना सिर्फ़ उनकी अपनी पिछली प्रकाशित परीक्षाओं से करते हैं।',
  'rc.card.rules': 'अनुपस्थित और छूट अंक नहीं हैं: वे कुल और प्रतिशत से बाहर रहते हैं।',
  'rc.card.publication': 'इस परिणाम का प्रकाशन {version}, {date} को {name} ने प्रकाशित किया।',
  'rc.card.publicationNoName': 'इस परिणाम का प्रकाशन {version}, {date} को प्रकाशित।',
  'rc.card.scheme': 'ग्रेड स्कूल की ग्रेडिंग योजना, संस्करण {version}, से, जो इस प्रकाशन के साथ रखी गई है।',
