  'cg.whoOffice': 'आप स्कूल की कोई भी कक्षा चुन सकते हैं।',
  'cg.whoTeacher': 'आपको अपनी कक्षाएँ दिखती हैं: जिनमें आप कोई विषय पढ़ाते हैं, और जिसके आप कक्षा-शिक्षक हैं।',
  'cg.noClasses.title': 'दिखाने को कोई कक्षा नहीं',
  'cg.noClasses.office': 'स्कूल में अभी कोई कक्षा नहीं है। पहले उन्हें Setup में जोड़ें।',
  'cg.noClasses.teacher': 'आपकी अभी कोई कक्षा नहीं है। ऑफ़िस आपको आपके विषय और आपकी कक्षा देता है।',
  'cg.noSubjects.title': 'अभी कोई विषय नहीं',
  'cg.noSubjects.do': 'स्कूल में अभी कोई विषय नहीं है। ऑफ़िस उन्हें Setup में जोड़ता है।',
  'cg.notSetUp.title': 'अभी तैयार नहीं',
  'cg.notSetUp.text': '{class} का {subject} के लिए अभी कोई पाठ्यक्रम का नक्शा नहीं है। Taught today में “Syllabus map” के अंदर इसके अध्याय और विषय-बिंदु जोड़ें।',
  'cg.notSetUp.action': 'Taught today खोलें',
  'cg.notSetUp.noLessons': 'सत्र {session} में {class} के {subject} का कोई पाठ अभी पढ़ाया हुआ दर्ज नहीं है। दूसरा सत्र चुनें, या Taught today में पाठ दर्ज करें।',
  'cg.notSetUp.noSession': 'अभी कोई शैक्षिक सत्र दर्ज नहीं है, इसलिए कोई कमी नहीं दिखाई जा सकती।',
  'cg.total.one': '{class} · {subject}: {count} इकाई',
  'cg.total.other': '{class} · {subject}: {count} इकाइयाँ',
