  'cg.state.taught-assessed': 'पढ़ाई और जाँची गई',
  'cg.state.taught-not-assessed': 'पढ़ाई गई, जाँची नहीं गई',
  'cg.state.skipped': 'छूट गई',
  'cg.state.not-yet-taught': 'अभी नहीं पढ़ाई गई',
  'cg.how.title': 'हर स्थिति कैसे तय होती है',
  'cg.how.taught': 'पढ़ाई गई: Taught today में इस इकाई का पाठ “Taught” दर्ज हुआ। कुछ पढ़ाया, टल गया और नहीं पढ़ाया वाले पाठ नहीं गिने जाते।',
  'cg.how.assessed': 'जाँची गई: यह इकाई इस कक्षा और विषय के किसी परीक्षा पेपर के अध्यायों में है।',
  'cg.how.assessed-before-taught': 'पढ़ाने से पहले जाँची गई: किसी पेपर में है, और या तो अभी नहीं पढ़ाई गई या पेपर की तारीख़ के बाद पहली बार पढ़ाई गई।',
  'cg.how.taught-assessed': 'पढ़ाई और जाँची गई: पढ़ाई गई, और ऐसे पेपर में है जिसकी तारीख़ पहले पाठ के दिन या उसके बाद की है, या जिसकी अभी तारीख़ नहीं है।',
  'cg.how.taught-not-assessed': 'पढ़ाई गई, जाँची नहीं गई: पढ़ाई गई, और अभी किसी परीक्षा पेपर में नहीं है।',
  'cg.how.skipped': 'छूट गई: कभी नहीं पढ़ाई गई और किसी पेपर में नहीं, जबकि नक्शे में उसके बाद की कोई इकाई पढ़ाई जा चुकी है।',
  'cg.how.not-yet-taught': 'अभी नहीं पढ़ाई गई: कभी नहीं पढ़ाई गई, किसी पेपर में नहीं, और उसके बाद की कोई इकाई भी नहीं पढ़ाई गई।',
  'cg.units.title': 'इकाइयाँ',
  'cg.units.order': 'पाठ्यक्रम के नक्शे के क्रम में। हर बार यह पेज खुलने पर Taught today और परीक्षा पेपरों से निकाला जाता है।',
