  'set.compliance.expiry_window.label': 'इतने दिनों में ख़त्म होने वाले प्रमाणपत्र दिखाएँ',
  'set.compliance.expiry_window.help': 'जिस TET प्रमाणपत्र या अन्य मंज़ूरी की मान्य-तक तारीख़ इतने दिनों में है, या निकल चुकी है, वह अनुपालन डेस्क और “मेरा दिन” पर दिखती है। ख़ाली मान्य-तक तारीख़ का मतलब कोई अंतिम तारीख़ नहीं।',
