  'set.compliance.pre_degree.label': 'पूर्व-प्राथमिक: डिग्री',
  'set.compliance.pre_degree.help': 'इस स्तर को पढ़ाने के लिए डिग्री ज़रूरी है: इस स्तर के जिस शिक्षक की यह दर्ज नहीं है, वह अनुपालन डेस्क पर कमी के रूप में दिखता है। कक्षा I से VIII के लिए TET शुरू से चालू है, जैसा RTE अधिनियम के तहत NCTE चाहता है; बाक़ी के लिए अपने बोर्ड और राज्य के नियम देखें।',
